public static class SubsetNormalizer
{
    public static List<List<int>> Normalize(List<List<int>> subsets)
    {
        var sorted = subsets.Select(s => { var c = new List<int>(s); c.Sort(); return c; }).ToList();
        sorted.Sort((a, b) =>
        {
            if (a.Count != b.Count) return a.Count - b.Count;
            for (var i = 0; i < a.Count; i++) if (a[i] != b[i]) return a[i] - b[i];
            return 0;
        });
        return sorted;
    }
}

